// Play a one-shot effect model, then delete it once its motion has finished
local hEffMdl = CMND_CREATE_CHARA(7, "CmrEff", "data/effect/ega0018.xc", "Effect");
CMND_SET_ENABLE(hEffMdl, 1);
while (CMND_IS_LOADING(hEffMdl))
{
	suspend();
}
CMND_SET_MOTION(hEffMdl, "01", 3, 0);
while (!CMND_CHR_MTN_IS_END(hEffMdl))
{
	suspend();
}
CMND_DELETE_CHARA(hEffMdl);
